import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function SellerLogin() {
    const navigate = useNavigate();
    const [loginData, setLoginData] = useState({
        email: '',
        password: ''
    });
    const [step, setStep] = useState(1); // 1: email check, 2: password entry, 3: set password
    const [sellerInfo, setSellerInfo] = useState(null);
    const [loading, setLoading] = useState(false);

    const handleEmailSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.email) {
            toast.error('Please enter your email');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email: loginData.email })
            });
            
            const data = await response.json();
            
            if (data.success) {
                if (data.needsPassword) {
                    setSellerInfo(data.data);
                    if (data.data && data.data.needsPasswordSetup) {
                        setStep(3); // Set password
                    } else {
                        setStep(2); // Enter password
                    }
                } else {
                    // Login successful, store user data and redirect
                    localStorage.setItem('studioToken', 'simulated-token');
                    localStorage.setItem('studioUser', JSON.stringify({
                        id: data.data.id,
                        email: data.data.email,
                        firstName: data.data.firstname,
                        lastName: data.data.lastname,
                        role: 'seller'
                    }));
                    toast.success('Login successful');
                    navigate('/studio/home'); // Redirect to post-login landing page
                }
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter your password');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/login-with-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                // Login successful, store user data and redirect
                localStorage.setItem('studioToken', 'simulated-token');
                localStorage.setItem('studioUser', JSON.stringify({
                    id: data.data.id,
                    email: data.data.email,
                    firstName: data.data.firstname,
                    lastName: data.data.lastname,
                    role: 'seller'
                }));
                toast.success('Login successful');
                navigate('/studio/home'); // Redirect to post-login landing page
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleSetPasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter a password');
            return;
        }

        if (loginData.password.length < 6) {
            toast.error('Password must be at least 6 characters long');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/set-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                toast.success('Password set successfully. Please login with your password.');
                setStep(2); // Go to password entry step
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Set password error:', error);
            toast.error('Failed to set password: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const renderEmailForm = () => (
        <form onSubmit={handleEmailSubmit}>
            <div className="mb-3">
                <label htmlFor="email" className="form-label">Email</label>
                <input
                    type="email"
                    className="form-control"
                    id="email"
                    name="email"
                    placeholder="Enter your email"
                    value={loginData.email}
                    onChange={(e) => setLoginData({...loginData, email: e.target.value})}
                    disabled={loading}
                    required
                />
            </div>

            <div className="mt-4">
                <button 
                    className="btn btn-success w-100" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Checking...
                        </>
                    ) : (
                        'Continue'
                    )}
                </button>
            </div>
        </form>
    );

    const renderPasswordForm = () => (
        <form onSubmit={handlePasswordSubmit}>
            <div className="mb-3">
                <label htmlFor="password" className="form-label">Password</label>
                <div className="position-relative auth-pass-inputgroup mb-3">
                    <input
                        type="password"
                        className="form-control pe-5 password-input"
                        placeholder="Enter your password"
                        id="password"
                        name="password"
                        value={loginData.password}
                        onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        disabled={loading}
                        required
                    />
                    <button className="btn btn-link position-absolute end-0 top-0 text-decoration-none text-muted password-addon" type="button">
                        <i className="ri-eye-fill align-middle"></i>
                    </button>
                </div>
            </div>

            <div className="mt-4">
                <button 
                    className="btn btn-success w-100" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Signing in...
                        </>
                    ) : (
                        'Sign In'
                    )}
                </button>
            </div>
        </form>
    );

    const renderSetPasswordForm = () => (
        <form onSubmit={handleSetPasswordSubmit}>
            <div className="alert alert-info">
                <p className="mb-0">
                    <i className="ri-information-line me-1"></i>
                    Welcome! Please set your password to complete your seller account setup.
                </p>
            </div>
            
            <div className="mb-3">
                <label htmlFor="newPassword" className="form-label">New Password</label>
                <div className="position-relative auth-pass-inputgroup mb-3">
                    <input
                        type="password"
                        className="form-control pe-5 password-input"
                        placeholder="Enter your new password"
                        id="newPassword"
                        name="password"
                        value={loginData.password}
                        onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        disabled={loading}
                        required
                    />
                    <button className="btn btn-link position-absolute end-0 top-0 text-decoration-none text-muted password-addon" type="button">
                        <i className="ri-eye-fill align-middle"></i>
                    </button>
                </div>
                <div className="form-text">Password must be at least 6 characters long</div>
            </div>

            <div className="mt-4">
                <button 
                    className="btn btn-success w-100" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Setting Password...
                        </>
                    ) : (
                        'Set Password'
                    )}
                </button>
            </div>
        </form>
    );

    return (
        <div className="auth-page-wrapper pt-5">
            <div className="auth-one-bg-position auth-one-bg" id="auth-element">
                <div className="bg-overlay"></div>
                <div className="shape">
                    <svg xmlns="http://www.w3.org/2000/svg" version="1.1" viewBox="0 0 1440 120">
                        <path d="M 0,36 C 144,53.6 432,123.2 720,124 C 1008,124.8 1296,56.8 1440,40L1440 140L0 140z"></path>
                    </svg>
                </div>
            </div>

            <div className="auth-page-content">
                <div className="container">
                    <div className="row">
                        <div className="col-lg-12">
                            <div className="text-center mt-sm-5 mb-4 text-white-50">
                                <div>
                                    <a href="/studio" className="d-inline-block auth-logo">
                                        <img src="/assets/images/logo-light.png" alt="" height="50" />
                                    </a>
                                </div>
                                <p className="mt-3 fs-15 fw-medium">Seller Login - Studio Platform</p>
                            </div>
                        </div>
                    </div>

                    <div className="row justify-content-center">
                        <div className="col-md-8 col-lg-6 col-xl-5">
                            <div className="card mt-4">
                                <div className="card-body p-4">
                                    <div className="text-center mt-2">
                                        <h5 className="text-primary">Seller Login</h5>
                                        <p className="text-muted">
                                            {step === 1 && "Enter your email to verify your seller account"}
                                            {step === 2 && "Enter your password to login"}
                                            {step === 3 && "Set your password to complete setup"}
                                        </p>
                                    </div>
                                    <div className="p-2 mt-4">
                                        {step === 1 && renderEmailForm()}
                                        {step === 2 && renderPasswordForm()}
                                        {step === 3 && renderSetPasswordForm()}
                                        
                                        {step > 1 && (
                                            <div className="mt-3">
                                                <button 
                                                    className="btn btn-link text-muted"
                                                    onClick={() => setStep(1)}
                                                    disabled={loading}
                                                >
                                                    <i className="ri-arrow-left-line me-1"></i>
                                                    Back to Email Verification
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="mt-4 text-center">
                                <p className="mb-0">
                                    Don't have an account?{' '}
                                    <a href="/studio/apply" className="fw-semibold text-primary text-decoration-underline">
                                        Apply for access
                                    </a>
                                </p>
                            </div>
                            
                            <div className="mt-2 text-center">
                                <p className="mb-0">
                                    <button 
                                        className="btn btn-link text-primary text-decoration-underline p-0"
                                        onClick={() => navigate('/studio')}
                                    >
                                        Back to Home
                                    </button>
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
